L13_1.m_Talk_ENG = "And the place death, considering who thou art."
L13_1.m_Talk_TWN = "\228\187\128\233\186\188\229\185\185\229\152\155\239\188\159\231\149\182\228\189\160\232\184\143\229\133\165\233\128\153\230\163\159\230\136\191\229\173\144\230\153\130\239\188\140\230\135\137\232\169\178\229\176\177\229\183\178\231\182\147\229\129\154\229\165\189\232\181\180\230\173\187\231\154\132\229\191\131\231\144\134\230\186\150\229\130\153\229\144\167\239\188\159"
