L36_1.m_Talk_TWN = "\230\156\131\233\149\183\239\188\140\228\189\160\229\134\183\233\157\156\233\187\158\239\188\129\228\189\160\233\128\153\233\186\188\232\170\141\231\156\159\229\185\185\229\152\155\239\188\159\233\128\153\229\143\170\230\152\175\229\189\169\230\142\146\232\128\140\229\183\178\230\172\184\239\188\129"
