L5_1 = "\230\137\139\227\129\171\232\178\160\227\129\136\227\129\170\227\129\132\227\130\136\227\129\134\227\129\170\229\135\132\227\129\190\227\129\152\227\129\132\229\138\155\226\128\166\226\128\166\n\227\129\157\227\129\174\233\153\144\231\149\140\227\130\146\231\160\180\227\130\140\227\129\176\227\128\129\231\167\129\227\130\146\229\128\146\227\129\153\227\129\147\227\129\168\227\130\130\227\129\167\227\129\141\227\130\139\227\129\167\227\129\151\227\130\135\227\129\134\227\128\130"
L4_1.m_Talk_JPN = L5_1
L5_1 = "A power beyond thy control... If thou art break the limit, then thou shall be able to defeat me."
L4_1.m_Talk_ENG = L5_1
