L6_1 = "\227\129\151\227\129\139\227\129\151\227\128\129\227\129\147\227\129\161\227\130\137\227\130\130\227\129\157\227\130\140\227\130\146\233\187\153\227\129\163\227\129\166\232\166\139\227\129\166\227\129\132\227\130\139\227\130\143\227\129\145\227\129\171\227\129\175\227\129\132\227\129\141\227\129\190\227\129\155\227\130\147\227\129\174\227\129\167\227\128\130"
