L27_1.m_fTalkTime = 0.03
L28_1 = "\227\129\147\227\129\147\227\129\175\226\128\166\226\128\166\227\129\147\227\129\174\229\173\166\230\160\161\227\129\175\226\128\166\226\128\166\231\167\129\227\129\159\227\129\161\227\129\140\229\133\131\227\128\133\227\129\132\227\129\159\229\160\180\230\137\128\227\129\152\227\130\131\227\129\170\227\129\132\227\128\130"
L27_1.m_Talk_JPN = L28_1
L28_1 = "This place... This school... It's not where we are from."
L27_1.m_Talk_ENG = L28_1
L28_1 = "\233\128\153\229\128\139\229\156\176\230\150\185\226\128\166\226\128\166\233\128\153\233\150\147\229\173\184\230\160\161\226\128\166\226\128\166\233\131\189\228\184\141\230\152\175\230\136\145\229\128\145\229\142\159\230\156\172\230\137\128\229\156\168\231\154\132\229\156\176\230\150\185\227\128\130"
