L13_1 = "\227\129\134\227\130\147\227\128\129\228\188\154\233\149\183\227\129\174\227\129\138\227\129\139\227\129\146\227\129\167\229\191\152\227\130\140\227\129\166\227\129\132\227\129\159\227\129\147\227\129\168\227\130\146\230\128\157\227\129\132\229\135\186\227\129\155\227\129\159\227\130\147\227\129\160\227\128\130"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Yeah, thanks to you, I was reminded of something I had forgotten."
L12_1.m_Talk_ENG = L13_1
L13_1 = "\229\151\175\239\188\140\230\139\156\230\156\131\233\149\183\230\137\128\232\179\156\239\188\140\230\136\145\230\137\141\232\131\189\230\131\179\232\181\183\233\129\186\229\191\152\231\154\132\228\186\139\227\128\130"
