L15_1 = "\227\129\157\227\129\134\227\128\130\227\129\168\227\129\166\227\130\130\229\164\167\229\136\135\227\129\170\227\129\147\227\129\168\227\128\130\227\129\168\227\129\171\227\129\139\227\129\143\227\129\130\227\130\138\227\129\140\227\129\168\227\129\134\227\128\129\228\188\154\233\149\183\227\128\130"
