L15_1 = "\230\178\146\233\140\175\239\188\140\231\156\159\230\173\163\233\135\141\232\166\129\231\154\132\228\186\139\226\128\166\226\128\166\231\184\189\228\185\139\239\188\140\232\172\157\232\172\157\230\156\131\233\149\183\227\128\130"
